import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.23 released — Payment 深化 (advanced billing semantics 9 axis + 3 dogfood merchant app)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.23/gh-discussions-announcement.md","filePath":"announcements/v1.23/gh-discussions-announcement.md"}'),s={name:"announcements/v1.23/gh-discussions-announcement.md"};function i(c,e,r,n,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="kiwa-v1-23-released-—-payment-深化-advanced-billing-semantics-9-axis-3-dogfood-merchant-app" tabindex="-1">kiwa v1.23 released — Payment 深化 (advanced billing semantics 9 axis + 3 dogfood merchant app) <a class="header-anchor" href="#kiwa-v1-23-released-—-payment-深化-advanced-billing-semantics-9-axis-3-dogfood-merchant-app" aria-label="Permalink to &quot;kiwa v1.23 released — Payment 深化 (advanced billing semantics 9 axis + 3 dogfood merchant app)&quot;">​</a></h1><p>v1.23 is out. After v1.14&#39;s payment layer landed the 3 provider webhook baseline (Stripe + Paddle + Lemon Squeezy HMAC signature verify + 4 fixture events), v1.23 layers <strong>9 axes of advanced billing semantics</strong> on top — dunning + retry + 3DS v2 + SCA + PSD2 mandate + subscription lifecycle + invoice lifecycle + VAT/GST/sales-tax + chargeback dispute. Provider-neutral state machines + strict transition guards + fidelity harness across all 3 providers. 100 new semantics behavior tests + 3 dogfood merchant apps + 3 tutorials + concept doc SSOT.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-test/payment</code> v0.3.0</strong> (9-axis advanced billing semantics). v0.2&#39;s webhook mock + 4 fixture events (<code>createStripeMock</code> / <code>createPaddleMock</code> / <code>createLemonSqueezyMock</code> / <code>signWebhook</code> / <code>emit</code> / <code>verify</code> / <code>checkoutCompleted</code> / <code>subscriptionCreated</code> / <code>paymentFailed</code> / <code>refunded</code>) keep every prior signature. v0.3 lands <code>packages/payment/src/semantics/*</code> — 1 axis = 1 file of pure state-machine helpers that operate on the shared <code>PaymentAdapter</code> interface every provider mock implements. Every axis emits a strongly typed <code>AxisStep</code> sequence so tests assert on the transitions, not the event names. <ul><li><code>dunning.ts</code> — Stripe Smart Retries envelope (<code>active</code> → <code>in-grace-period</code> → <code>recovered</code> or <code>exhausted</code>, default <code>maxAttempts: 4</code>, <code>retryIntervalMs: 3 days</code>, <code>gracePeriodMs: 1 day</code>)</li><li><code>retry.ts</code> — general-purpose exponential backoff with jitter (<code>pending</code> → <code>retrying</code> → <code>delivered</code> or <code>dead-letter</code>, default <code>maxAttempts: 5</code>)</li><li><code>three-ds.ts</code> — EMVCo 3DS 2.2 challenge flow (<code>fingerprint</code> → <code>challenge-pending</code> → <code>completed</code>, or <code>fingerprint</code> → <code>frictionless</code>, accepts all 6 <code>transStatus</code> codes <code>Y</code>/<code>N</code>/<code>A</code>/<code>C</code>/<code>U</code>/<code>R</code>)</li><li><code>sca.ts</code> — PSD2 Strong Customer Authentication (6 exemption categories — low-value / low-risk / trusted-beneficiary / secure-corporate / recurring / MIT)</li><li><code>psd2.ts</code> — SEPA direct debit / BACS / ACH mandate (<code>pending</code> → <code>active</code> → <code>revoked</code> + consent-timestamp)</li><li><code>subscription-lifecycle.ts</code> — 5-state envelope (<code>active</code> → <code>upgraded</code> / <code>downgraded</code> / <code>paused</code> / <code>canceled</code> + <code>paused</code> → <code>resumed</code> + <code>canceled</code> → <code>reactivated</code>) with strict transition guards</li><li><code>invoice.ts</code> — <code>draft</code> → <code>open</code> → (<code>paid</code> | <code>void</code> | <code>uncollectible</code>) + credit-note support</li><li><code>tax.ts</code> — VAT / GST / sales-tax auto-calc across ~180 jurisdictions + reverse charge for B2B EU customers with a valid VAT ID</li><li><code>chargeback.ts</code> — card-network dispute lifecycle (<code>opened</code> → <code>evidence-submitted</code> → <code>won</code> or <code>lost</code> with provider-specific fee assessment)</li></ul></li><li><strong><code>examples/dogfood-stripe-billing-app</code></strong> — Next.js 15 App Router merchant app wired to Stripe. <code>createStripeMock</code> drives checkout session + webhook endpoint + subscription lifecycle + invoice + 3D Secure v2 + Smart Retries dunning across 35 vitest. The <code>KIWA_MODE=real</code> env-gate flips the entire suite from mock to the real Stripe sandbox without touching test bodies. Every axis semantic (dunning / retry / 3DS / SCA / subscription / invoice / tax / chargeback) exercises the same 4-method adapter surface.</li><li><strong><code>examples/dogfood-paddle-merchant-app</code></strong> — Nuxt 3 merchant-of-record app wired to Paddle Billing v2. <code>createPaddleMock</code> drives inline checkout (<code>Paddle.Checkout.open</code> instead of hosted redirect), tier upgrade with proration, VAT/GST/sales-tax auto-calc, and reverse-charge for B2B intra-EU customers. 40 vitest. Paddle acts as Merchant-of-Record so the app never touches PSP details — Paddle handles fraud + chargeback + tax registration and the app just books neutralised events.</li><li><strong><code>examples/dogfood-lemon-squeezy-app</code></strong> — SvelteKit merchant-of-record app wired to Lemon Squeezy. <code>createLemonSqueezyMock</code> drives hosted checkout (URL redirect, no inline SDK), license key issue+activate+revoke, refund full+partial via the neutral <code>refunded</code> fixture, and full chargeback dispute lifecycle (opened → evidence-submitted → won/lost + fee assessment). 74 vitest — the widest v1.23 dogfood app because license flow doubles as a chargeback signal source.</li><li><strong>docs</strong> — 3 new tutorials (39 Stripe advanced billing + 40 Paddle merchant-of-record + 41 Lemon Squeezy license flow) + concept doc <code>billing-semantics.md</code> — SSOT for the 9 axes + provider-specific fidelity surface across all 3 dogfood merchant apps. Migration guide v1.22 → v1.23 (additive-only). Snippet validation test <code>packages/payment/tests/docs-tutorial-v1.23.test.ts</code> (18 tests) re-runs every code snippet against the real <code>@kiwa-test/payment</code> API. Same drift-detection pattern as <code>docs-tutorial-v1.21.test.ts</code> + <code>docs-tutorial-v1.22.test.ts</code>. VitePress sidebar gains a <code>Payment 深化 (v1.23)</code> tutorial section; gh-pages published via <code>/docs-publish-kiwa</code>.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#900-#905)</li><li><strong>6 PRs merged</strong> (v1.23-1 + v1.23-2 + v1.23-3 + v1.23-4 + v1.23-5 + this publish PR)</li><li><strong>1 npm minor bump</strong> (<code>@kiwa-test/payment</code> v0.2.0 → v0.3.0) — kiwa runtime fixture count stays 34</li><li><strong>3 new dogfood merchant apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>~267 new tests</strong> across 9 semantics axes (100) + Stripe (35) + Paddle (40) + Lemon Squeezy (74) + snippet validation (18)</li></ul><h2 id="why-9-axes-and-not-just-webhook-mock" tabindex="-1">Why 9 axes (and not just webhook mock) <a class="header-anchor" href="#why-9-axes-and-not-just-webhook-mock" aria-label="Permalink to &quot;Why 9 axes (and not just webhook mock)&quot;">​</a></h2><p>Payment testing has three failure modes that a webhook-only mock can&#39;t catch, no matter how many fixture events you pack in.</p><ul><li><strong>State-machine drift</strong> — a subscription&#39;s real lifecycle isn&#39;t <code>active</code> / <code>canceled</code>; it&#39;s a 5-state graph with transition guards (<code>active</code> → <code>upgraded</code> → <code>downgraded</code> → <code>paused</code> → <code>canceled</code>, with <code>reactivate</code> only allowed from <code>canceled</code>). Tests that assert <code>event.type === &#39;customer.subscription.created&#39;</code> miss the guards, and production bugs surface as invalid transitions the merchant app permits but the provider rejects.</li><li><strong>Retry cadence</strong> — real dunning is 4 attempts over ~1 week + a grace period. Tests that skip the retry loop miss uncollectible-flip regressions and let merchant apps ship without the grace-period UX.</li><li><strong>Cross-provider fidelity</strong> — Stripe defers proration to the next invoice; Paddle charges the difference immediately; Lemon Squeezy hosts checkout while Paddle inlines it. A neutral test surface makes these differences <strong>explicit assertions</strong>, not silent regressions.</li></ul><p>The 9 axes are the smallest set that reproduces the full billing envelope across the 3 target providers. Each axis is an independent module under <code>@kiwa-test/payment/semantics/*</code>; each provides pure functions that operate on the shared <code>PaymentAdapter</code> interface + emit a strongly typed <code>AxisStep</code> sequence so tests can assert on the transitions, not the event shapes.</p><h2 id="_3-dogfood-merchant-apps-—-one-adapter-surface-three-billing-envelopes" tabindex="-1">3 dogfood merchant apps — one adapter surface, three billing envelopes <a class="header-anchor" href="#_3-dogfood-merchant-apps-—-one-adapter-surface-three-billing-envelopes" aria-label="Permalink to &quot;3 dogfood merchant apps — one adapter surface, three billing envelopes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>Framework</th><th>Distinguishing axes</th></tr></thead><tbody><tr><td><code>dogfood-stripe-billing-app</code></td><td>Next.js 15 App Router</td><td>Checkout session + webhook endpoint + subscription lifecycle + invoice + 3D Secure v2 + Smart Retries dunning</td></tr><tr><td><code>dogfood-paddle-merchant-app</code></td><td>Nuxt 3</td><td>Inline checkout (<code>Paddle.Checkout.open</code>) + tier upgrade with proration + VAT/GST/sales-tax auto-calc + reverse-charge B2B EU</td></tr><tr><td><code>dogfood-lemon-squeezy-app</code></td><td>SvelteKit</td><td>Hosted checkout (URL redirect) + license key issue+activate+revoke + refund full+partial + chargeback dispute lifecycle (opened → evidence → won/lost)</td></tr></tbody></table><p>All three share the same <code>KIWA_MODE=mock|real-optional|real</code> switch v1.22 established — mock branch runs in ~1 ms per test; <code>KIWA_MODE=real</code> flips to the actual provider sandbox without touching bodies.</p><h2 id="_13-milestone-streak" tabindex="-1">13-milestone streak <a class="header-anchor" href="#_13-milestone-streak" aria-label="Permalink to &quot;13-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → v1.19 (Framework 深化) → v1.20 (Streaming 深化) → v1.21 (Auth 深化) → v1.22 (Auth 深化 II) → <strong>v1.23 (Payment 深化)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100% milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li><li>DB depth (SurrealDB / EdgeDB / Turso)</li><li>Payment 深化 II — real driver layer (real Stripe / Paddle / Lemon Squeezy sandbox testcontainers + <code>KIWA_MODE=real-required</code> nightly)</li></ul><p>Feedback welcome on which of these should land next.</p>',18)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
